            link.setParentSheet(parent);
            parents.save(link);
        }
        parents.flush();
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + user.strip() + " key=parent value="
                + (parent == null ? "" : parent));
        rollup.recordChanges(sheetId, user, before);
        return parent;
